INSERT INTO products (id,name,category,description,price_minor,image,alt,sizes,colors,featured,brand,subcategory,mrp_minor,discount_percent,material,fit,rating_value,rating_scale,rating_count,source_store,source_product_id,canonical_url,verification_status,missing_fields) VALUES ('source-women-005','GRECIILOOKS Women’s Co-Ord Set','women','Elevate your style with our Women''s Co-ord Set, the perfect two-piece outfit designed to make you look and feel fantastic. This stunning co-ordinate ensemble is a must-have addition to your wardrobe, offering a blend of comfort and fashion that''s perfect for any occasion. Crafted with the latest trends in mind, our Co-ord Set for Women includes a matching top and bottom, making it easy to create a cohesive and stylish look. The set is versatile, suitable for both casual outings and special events, ensuring you''re always fashion-forward. Stay effortlessly chic with our Stylish Two-Piece Ensemble, available in various colors and styles to suit your personal taste. Whether you''re looking for a Summer Co-ord Set for your vacation or a Chic Two-Piece Co-ord for a night out, we''ve got you covered. The Co-ord Set features top-quality materials, offering comfort and breathability, ensuring you look and feel your best. The Crop Top and Skirt Co-ord is perfect for warm-weather days, while our Trendy Matching Separates provide a trendy and contemporary fashion statement. Our Women''s Co-ord Set has been designed with attention to detail, and we know you''ll love the stylish and coordinated look it provides. So why wait? Elevate your fashion game with our Women''s Co-ord Set and get ready to turn heads. Discover the perfect co-ord outfit with our fashionable Two-Piece Co-ords. Whether you''re lounging at home or stepping out for a special event, our Co-ord Set for Women ensures you''re always ahead of the fashion curve. Shop now and enjoy the convenience of coordinated fashion!',69900,'https://m.media-amazon.com/images/I/51SllsCXWXL._SY741_.jpg','GRECIILOOKS Women’s Co-Ord Set product image','[]','[]',0,NULL,NULL,NULL,NULL,'Cotton Blend',NULL,'4.1',5,1268,'Amazon India','B0F6XNSQMQ','https://www.amazon.in/GRECIILOOKS-Spandex-Ethnic-Wear-Women/dp/B0F6XNSQMQ','verified','["color","sizes","brand","subcategory","mrp_inr","discount_percent","fit"]') ON CONFLICT(id) DO UPDATE SET name=excluded.name,category=excluded.category,description=excluded.description,price_minor=excluded.price_minor,image=excluded.image,alt=excluded.alt,sizes=excluded.sizes,colors=excluded.colors,featured=excluded.featured,brand=excluded.brand,subcategory=excluded.subcategory,mrp_minor=excluded.mrp_minor,discount_percent=excluded.discount_percent,material=excluded.material,fit=excluded.fit,rating_value=excluded.rating_value,rating_scale=excluded.rating_scale,rating_count=excluded.rating_count,source_store=excluded.source_store,source_product_id=excluded.source_product_id,canonical_url=excluded.canonical_url,verification_status=excluded.verification_status,missing_fields=excluded.missing_fields;
