INSERT INTO products (id,name,category,description,price_minor,image,alt,sizes,colors,featured,brand,subcategory,mrp_minor,discount_percent,material,fit,rating_value,rating_scale,rating_count,source_store,source_product_id,canonical_url,verification_status,missing_fields) VALUES ('source-women-008','Jegging with full sleeve denim co-ord set','women','The Belore Slims Coord Set Jegging with Full Sleeve Crop Top is Crafted from a premium blend of 91% cotton and 9% spandex, this co-ord set offers a soft, breathable feel with the perfect amount of stretch for all-day ease. The advanced 4-way stretch fabric moves naturally with your body, providing maximum flexibility, comfort, and a flattering fit. Featuring curve-enhancing jeggings paired with a stylish full-sleeve crop top designed for the perfect blend of comfort and confidence, hugs your curves beautifully giving a sleek, modern look. Perfect for casual everyday wear, gym or yoga.',274900,'https://www.beloreslims.com/cdn/shop/files/Dark_Indigo-_Coord_1024x1024.jpg?v=1778325476','Jegging with full sleeve denim co-ord set product image','[]','[]',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Belore Slims',NULL,'https://www.beloreslims.com/products/jegging-with-full-sleeve-denim-coord-set?variant=51300243800342','verified','["color","sizes","brand","subcategory","mrp_inr","discount_percent","material","fit","rating","source_product_id"]') ON CONFLICT(id) DO UPDATE SET name=excluded.name,category=excluded.category,description=excluded.description,price_minor=excluded.price_minor,image=excluded.image,alt=excluded.alt,sizes=excluded.sizes,colors=excluded.colors,featured=excluded.featured,brand=excluded.brand,subcategory=excluded.subcategory,mrp_minor=excluded.mrp_minor,discount_percent=excluded.discount_percent,material=excluded.material,fit=excluded.fit,rating_value=excluded.rating_value,rating_scale=excluded.rating_scale,rating_count=excluded.rating_count,source_store=excluded.source_store,source_product_id=excluded.s