ategory=excluded.subcategory,mrp_minor=excluded.mrp_minor,discount_percent=excluded.discount_percent,material=excluded.material,fit=excluded.fit,rating_value=excluded.rating_value,rating_scale=excluded.rating_scale,rating_count=excluded.rating_count,source_store=excluded.source_store,source_product_id=excluded.source_product_id,canonical_url=excluded.canonical_url,verification_status=excluded.verification_status,missing_fields=excluded.missing_fields;
